p:8px;">                <button type="button" class="button button-primary" id="mg-regenerate-all" data-nonce="<?php echo esc_attr( $megagovern_nonce_regenerate ); ?>" style="width:100%;text-align:center;">                    <?php echo wp_kses_post( megagovern_disclosures_icon( 'refresh-cw', '14' ) ); ?>                    <?php esc_html_e( 'Regenerate All Assets', 'megagovern' ); ?>                </button>                <button type="button" class="button button-secondary" id="mg-clear-cache" data-nonce="<?php echo esc_attr( $megagovern_nonce_maintenance ); ?>" style="width:100%;text-align:center;">                    <?php echo wp_kses_post( megagovern_disclosures_icon( 'trash-2', '14' ) ); ?>                    <?php esc_html_e( 'Clear Generated Cache', 'megagovern' ); ?>                </button>                <button type="button" class="button button-secondary" id="mg-rebuild-files" data-nonce="<?php echo esc_attr( $megagovern_nonce_maintenance ); ?>" style="width:100%;text-align:center;">                    <?php echo wp_kses_post( megagovern_disclosures_icon( 'refresh-cw', '14' ) ); ?>                    <?php esc_html_e( 'Rebuild Public Files', 'megagovern' ); ?>                </button>            </div>        </div>    </div></div><!-- ============================================================ --><!-- JAVASCRIPT                                                   --><!-- ============================================================ --><script>(function($) {    'use strict';    var ajaxUrl = '<?php echo esc_js( admin_url( 'admin-ajax.php' ) ); ?>';    // ─── Copy URL ───    $(document).on('click', '.mga-copy-btn', function() {        var url = $(this).data('copy');        if (!url) return;        navigator.clipboard.writeText(url).then(function() {            var $btn = $(this);            var original = $btn.html();            $btn.html('<?php echo esc_js( __( 'Copied', 'megagovern' ) ); ?>');            setTimeout(function() { $btn.html(original); }, 2000);        }.bind(this)).catch(function() {            alert('<?php echo esc_js( __( 'Failed to copy.', 'megagovern' ) ); ?>');        });    });    // ─── Copy as Markdown (LLMs.txt) ───    $(document).on('click', '.mga-copy-md-btn', function() {        var $btn = $(this);        var url = $btn.data('copy-url');        var nonce = $btn.data('nonce');        if (!url || !nonce) return;        $btn.prop('disabled', true).text('<?php echo esc_js( __( 'Fetching...', 'megagovern' ) ); ?>');        fetch(url)            .then(function(response) { return response.text(); })            .then(function(text) {                var mdContent = '```\n' + text + '\n```';                return navigator.clipboard.writeText(mdContent);            })            .then(function() {                var original = '<?php echo esc_js( __( 'Copy as MD', 'megagovern' ) ); ?>';                $btn.html('<?php echo esc_js( __( 'Copied', 'megagovern' ) ); ?>');                setTimeout(function() { $btn.prop('disabled', false).text(original); }, 2000);            })            .catch(function() {                alert('<?php echo esc_js( __( 'Failed to copy.', 'megagovern' ) ); ?>');                $btn.prop('disabled', false).text('<?php echo esc_js( __( 'Copy as MD', 'megagovern' ) ); ?>');            });    });    // ─── Regenerate Single File ───    $(document).on('click', '.mga-regen-single-btn', function() {        var $btn = $(this);        var file = $btn.data('file');        var nonce = $btn.data('nonce');        if (!file || !nonce) return;        $btn.prop('disabled', true).html('<?php echo esc_js( __( '...', 'megagovern' ) ); ?>');        $.ajax({            url: ajaxUrl,            type: 'POST',            data: {                action: 'megagovern_regenerate_file',                file: file,                nonce: nonce            },            success: function() {                $btn.html('<?php echo esc_js( __( 'Done', 'megagovern' ) ); ?>');                setTimeout(function() {                    $btn.prop('disabled', false).html('<?php echo wp_kses_post( megagovern_disclosures_icon( 'refresh-cw', '14' ) ); ?>');                }, 2000);            },            error: function() {                $btn.prop('disabled', false).html('<?php echo wp_kses_post( megagovern_disclosures_icon( 'refresh-cw', '14' ) ); ?>');            }        });    });    // ─── Regenerate All ───    $('#mg-regenerate-all').on('click', function() {        var $btn = $(this);        var nonce = $btn.data('nonce');        if (!nonce) return;        $btn.prop('disabled', true).text('<?php echo esc_js( __( 'Regenerating...', 'megagovern' ) ); ?>');        $.ajax({            url: ajaxUrl,            type: 'POST',            data: {                action: 'megagovern_regenerate_all',                nonce: nonce            },            success: function() {                $btn.html('<?php echo esc_js( __( 'Done', 'megagovern' ) ); ?>');                setTimeout(function() {                    $btn.prop('disabled', false).html('<?php echo wp_kses_post( megagovern_disclosures_icon( 'refresh-cw', '14' ) ); ?> <?php echo esc_js( __( 'Regenerate All Assets', 'megagovern' ) ); ?>');                }, 2000);            },            error: function() {                $btn.prop('disabled', false).html('<?php echo wp_kses_post( megagovern_disclosures_icon( 'refresh-cw', '14' ) ); ?> <?php echo esc_js( __( 'Retry', 'megagovern' ) ); ?>');            }        });    });    // ─── Clear Cache ───    $('#mg-clear-cache').on('click', function() {        var $btn = $(this);        var nonce = $btn.data('nonce');        if (!nonce) return;        $btn.prop('disabled', true).text('<?php echo esc_js( __( 'Clearing...', 'megagovern' ) ); ?>');        $.ajax({            url: ajaxUrl,            type: 'POST',            data: {                action: 'megagovern_clear_cache',                nonce: nonce            },            success: function() {                $btn.html('<?php echo esc_js( __( 'Cleared', 'megagovern' ) ); ?>');                setTimeout(function() {                    $btn.prop('disabled', false).html('<?php echo wp_kses_post( megagovern_disclosures_icon( 'trash-2', '14' ) ); ?> <?php echo esc_js( __( 'Clear Generated Cache', 'megagovern' ) ); ?>');                }, 2000);            },            error: function() {                $btn.prop('disabled', false).html('<?php echo wp_kses_post( megagovern_disclosures_icon( 'trash-2', '14' ) ); ?> <?php echo esc_js( __( 'Retry', 'megagovern' ) ); ?>');            }        });    });    // ─── Rebuild Public Files ───    $('#mg-rebuild-files').on('click', function() {        var $btn = $(this);        var nonce = $btn.data('nonce');        if (!nonce) return;        $btn.prop('disabled', true).text('<?php echo esc_js( __( 'Rebuilding...', 'megagovern' ) ); ?>');        $.ajax({            url: ajaxUrl,            type: 'POST',            data: {                action: 'megagovern_rebuild_files',                nonce: nonce            },            success: function() {                $btn.html('<?php echo esc_js( __( 'Done', 'megagovern' ) ); ?>');                setTimeout(function() {                    $btn.prop('disabled', false).html('<?php echo wp_kses_post( megagovern_disclosures_icon( 'refresh-cw', '14' ) ); ?> <?php echo esc_js( __( 'Rebuild Public Files', 'megagovern' ) ); ?>');                }, 2000);            },            error: function() {                $btn.prop('disabled', false).html('<?php echo wp_kses_post( megagovern_disclosures_icon( 'refresh-cw', '14' ) ); ?> <?php echo esc_js( __( 'Retry', 'megagovern' ) ); ?>');            }        });    });})(jQuery);</script>